const $tabelData = $('#tabelData'),
    $formData = $('#formData'),
    $modalDiv = $('#modalDiv'),
    $bahanJenisId = $('#bahan_jenis_id'),
    formCek = CirebonwebForm.FormCek($formData);

function loadBahanJenis(mesinTipeId, selectedId, callback) {
    $bahanJenisId.prop('disabled', true).prop('required', Boolean(mesinTipeId)).empty().append('<option value="">-- Pilih --</option>');

    if (!mesinTipeId) {
        $bahanJenisId.val('').trigger('change');
        $('.bahan_id').hide();
        if (callback) callback();
        return;
    }

    $.post(`${urlThis}/getbahanjenis`, { mesin_id: mesinTipeId }, function (rows) {
        rows.forEach(function (row) {
            $bahanJenisId.append(`<option value="${row.id}" data-rumus="${row.rumus}">${row.nama}</option>`);
        });
        $bahanJenisId.prop('disabled', false).val(selectedId || '').trigger('change');
        $('.bahan_id').show();
        if (callback) callback();
    }).fail(function () {
        Swal.fire({
            icon: 'error',
            title: 'Gagal memuat bahan',
            text: 'Silakan coba lagi.'
        });
    });
}

function setPromoState(enabled) {
    const $promoCheck = $('#promoCek input[type="checkbox"]');
    const $promoFields = $('#promo, #promo_awal, #promo_akhir');

    $promoCheck.prop('checked', enabled);
    $promoFields
        .prop('readonly', !enabled)
        .prop('required', enabled);

    if (!enabled) {
        $promoFields.val('');
    }
}

$(function () {
    $tabelData.DataTable({
        processing: true,
        serverSide: true,
        ajax: {
            url: `${urlThis}/tabel`,
            type: 'POST',
            data: function (d) {
                d.filter_kategori = $('#filter_kategori').val();
                d.filter_status = $('#filter_status').val();
            }
        },
        autoWidth: false,
        responsive: true,
        search: { return: true },
        dom: 'Blfrtip',
        buttons: [
            { text: 'Add', action: () => simpan() },
            {
                text: 'Reload',
                action: function (e, dt) {
                    dt.search('').draw();
                    $('#filter_kategori, #filter_status').val('').trigger('change');
                    Swal.fire({ icon: 'success', title: 'Informasi', text: 'Selesai reload tabel ke kondisi awal', showConfirmButton: false, timer: 1300 })
                        .then(function () { dt.ajax.reload(null, true); });
                }
            },
            { extend: 'excelHtml5', exportOptions: { columns: ':not(.no-export)', orthogonal: 'export' } }
        ],
        columnDefs: [
            { targets: '_all', className: 'dt-head-center' },
            { targets: [0, 14], className: 'dt-body-center' },
            { targets: [4, 5, 6], className: 'dt-body-right', render: CirebonwebFormat.RupiahTabel },
            { targets: [7, 8, 12, 13], render: function (data, type, row) { return CirebonwebFormat.Tanggal(data) } },
            { targets: [4, 5, 6, 14], orderable: false },
        ]
    });

    $('#tabelData_filter.dataTables_filter').append($('#filter_kategori, #filter_status'));
    $(document).on('change', '#filter_kategori, #filter_status', function () {
        $tabelData.DataTable().ajax.reload(null, false);
    });

    $('.tanggal').datepicker({
        dateFormat: 'dd-mm-yy'
    });

    $(document).on('change', '#promoCek input[type="checkbox"]', function () {
        setPromoState(this.checked);
    });

    $('#mesin_tipe_id').on('change', function (event, selectedBahanId) {
        loadBahanJenis($(this).val(), selectedBahanId);
    });

    $modalDiv
        .on('shown.bs.modal', function () {
            $('.select2').select2({ dropdownParent: $modalDiv });
            formCek.resetInitial();
        })
        .on('hidden.bs.modal', function () {
            CirebonwebForm.FormReset(this);
            $bahanJenisId.prop('disabled', true);
            $('#rumus').prop('disabled', false);
            $('.select2.select2-hidden-accessible').select2('destroy');
            setPromoState(false);
        });
});

function simpan(id) {
    const $modalTitle = $('.modal-title'),
        $btnSubmit = $('#btnSubmit'),
        postUrl = `${urlThis}/simpan`;

    if (id > 0) {
        CirebonwebForm.FormFetch(`${urlThis}/getid`, { id }, 'POST', {}).done(function (res) {
            if (!res.success) return;
            $modalTitle.text('Edit Data');
            $btnSubmit.text('Update');
            $('#id').val(res.data.id);
            $('#nama').val(res.data.nama);
            $('#kategori').val(res.data.kategori);
            $('#material_jenis_id').val(res.data.material_jenis_id || '').trigger('change');
            $('#rumus').val(res.data.rumus);
            const mesinTipeId = res.data.mesin_tipe_id || '';
            $('#mesin_tipe_id').val(mesinTipeId);
            $('#lebar').val(CirebonwebFormat.Desimal(res.data.lebar) || 0);
            $('#panjang').val(CirebonwebFormat.Desimal(res.data.panjang) || 0);
            // $('#status').val(res.data.status);
            $('#hpp').val(CirebonwebFormat.Rupiah(res.data.hpp));
            $('#harga').val(CirebonwebFormat.Rupiah(res.data.harga));
            $('#promo').val(CirebonwebFormat.Rupiah(res.data.promo));
            CirebonwebFormat.isoTanggal('promo_awal', res.data.promo_awal);
            CirebonwebFormat.isoTanggal('promo_akhir', res.data.promo_akhir);
            setPromoState(res.data.promo != null && res.data.promo !== '');
            loadBahanJenis(mesinTipeId, res.data.bahan_jenis_id, function () {
                $modalDiv.modal('show');
            });
        });
    } else {
        $modalTitle.text('Tambah Data');
        $btnSubmit.text('Simpan');
        $('#mesin_tipe_id').val('').trigger('change');
        $('.bahan_id').hide();
        $bahanJenisId.prop('disabled', true);
        $('#rumus').val('0').prop('disabled', false);
        $('#material_jenis_id').val('').trigger('change');
        setPromoState(false);
        $modalDiv.modal('show');
    }

    $formData.validate($.extend(CirebonwebForm.FormValidasi(), {
        rules: {
            bahan_jenis_id: {
                digits: true,
                required: function () {
                    return Boolean($('#mesin_tipe_id').val());
                }
            },
            kategori: { required: true, digits: true },
            nama: { required: true, minlength: 3, maxlength: 100 },
            lebar: { required: true, min: 0, max: 999.99 },
            panjang: { required: true, min: 0, max: 999.99 },
            rumus: { required: true, digits: true },
            // unggulan: { required: true, digits: true },
            // status: { required: true, digits: true }
        },
        submitHandler: function () {
            if (!formCek.isChanged()) return false;

            if ($('#promoCek input[type="checkbox"]').prop('checked')) {
                const promoAwalInput = $('#promo_awal').val();
                const promoAkhirInput = $('#promo_akhir').val();
                const promoAwal = CirebonwebFormat.sqlTanggal(promoAwalInput);
                const promoAkhir = CirebonwebFormat.sqlTanggal(promoAkhirInput);

                const dateErrors = {};
                if (promoAwalInput && !promoAwal) {
                    dateErrors.promo_awal = 'Format tanggal promo awal harus dd-mm-yyyy yang valid.';
                }
                if (promoAkhirInput && !promoAkhir) {
                    dateErrors.promo_akhir = 'Format tanggal promo akhir harus dd-mm-yyyy yang valid.';
                }
                if (Object.keys(dateErrors).length) {
                    $formData.validate().showErrors(dateErrors);
                    return false;
                }

                if (promoAwal && promoAkhir && promoAkhir <= promoAwal) {
                    $formData.validate().showErrors({
                        promo_akhir: 'Tanggal promo akhir harus lebih besar dari tanggal promo awal.'
                    });
                    return false;
                }
            }

            const data = $formData.serializeArray();
            if (!data.some(function (item) { return item.name === 'rumus'; })) {
                data.push({ name: 'rumus', value: $('#rumus').val() });
            }

            data.forEach(function (item) {
                if (['hpp', 'harga', 'promo'].includes(item.name)) {
                    item.value = CirebonwebFormat.unRupiah(item.value);
                } else if (['promo_awal', 'promo_akhir'].includes(item.name)) {
                    item.value = item.value ? CirebonwebFormat.sqlTanggal(item.value) : '';
                }
            });

            CirebonwebForm.FormFetch(postUrl, data, 'POST', {
                before_call: function () {
                    $btnSubmit.attr('disabled', true).html('<span class="spinner-border spinner-border-sm mr-1"></span> Loading...');
                },
                after_call: function () { $btnSubmit.attr('disabled', false).html('Simpan'); }
            }).done(function (response) {
                if (!response.success) return;
                $modalDiv.modal('hide');
                Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                    .then(function () { $tabelData.DataTable().ajax.reload(null, false); });
            });
            return false;
        }
    }));
}

function hapus(id) {
    Swal.fire({
        title: 'Konfirmasi',
        html: 'Apakah yakin ingin menghapus data ini? <br> Data akan dihapus secara permanen!',
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#d33',
        confirmButtonText: 'Ya, hapus!'
    }).then(function (result) {
        if (!result.isConfirmed) return;
        CirebonwebForm.FormFetch(`${urlThis}/hapus`, { id }, 'POST', {}).done(function (response) {
            if (!response.success) return;
            Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                .then(function () { $tabelData.DataTable().ajax.reload(null, false); });
        });
    });
}
